describe('validatePluginName', () => {
  beforeEach(() => {
    jest.clearAllMocks()
  })

  it('throws a TypeError if the plugin name is undefined', () => {
    const plugin = {}
    expect(() => validatePluginName(plugin)).toThrow(TypeError)
    expect(() => validatePluginName(plugin)).toThrow('The plugin is missing a "name"')
  })

  it('throws a TypeError if the plugin name is not a string', () => {
    const plugin = { name: 123 }
    expect(() => validatePluginName(plugin)).toThrow(TypeError)
    expect(() => validatePluginName(plugin)).toThrow('The plugin "name" must be a string: 123')
  })

  it('throws a TypeError if the plugin name is an object', () => {
    const plugin = { name: {} }
    expect(() => validatePluginName(plugin)).toThrow(TypeError)
  })

  it('calls validateNameString with the name when it is a valid string', () => {
    const plugin = { name: 'validplugin' }
    validateNameString.mockImplementation(() => {})

    validatePluginName(plugin)

    expect(validateNameString).toHaveBeenCalledWith('validplugin')
  })

  it('returns the plugin object with a fullName property', () => {
    const plugin = { name: 'myplugin' }
    validateNameString.mockImplementation(() => {})

    const result = validatePluginName(plugin)

    expect(result.fullName).toBe('modern-errors-myplugin')
    expect(result.name).toBe('myplugin')
  })

  it('does not mutate the original plugin object', () => {
    const plugin = { name: 'original' }
    validateNameString.mockImplementation(() => {})

    const result = validatePluginName(plugin)

    expect(plugin).not.toHaveProperty('fullName')
    expect(result).not.toBe(plugin)
  })
})

