    addInstanceMethod({ plugin: mockPlugin, plugins: mockPlugins, ErrorClass: mockErrorClass }, [mockMethodName, mockMethodFunc]);

    const boundMethod = setNonEnumProp.mock.calls.find(call => call[0] === mockErrorClass.prototype && call[1] === mockMethodName)[2];

