      methodFunc: mockMethodFunc,
      methodName: mockMethodName,
      plugin: mockPlugin,
      plugins: mockPlugins,
      ErrorClass: mockErrorClass,
      args: mockArgs,
    });
  });

  it('should call callMixedMethod when static method is invoked', () => {
    const { callMixedMethod } = require('../../../../src/plugins/instance/callMixedMethod');
