const path = require('path');

// Path resolution helpers
const srcPath = path.resolve(__dirname, '../../../../src/plugins/shape/main.js');
const mocksPath = path.resolve(__dirname, '../../../../src/plugins/shape');

// We require the dependencies first to ensure they are registered in the module cache before mocking
// This is sometimes necessary in Jest/Rollup environments to resolve paths correctly
const validatePluginNamePath = path.join(mocksPath, 'validatePluginName');
const validateOptionalFuncsPath = path.join(mocksPath, 'validateOptionalFuncs');
const normalizeAllMethodsPath = path.join(mocksPath, 'normalizeAllMethods');
const validateSameMethodsPath = path.join(mocksPath, 'validateSameMethods');
const normalizeIsOptionsPath = path.join(mocksPath, 'normalizeIsOptions');
const normalizeGetOptionsPath = path.join(mocksPath, 'normalizeGetOptions');

// Mock the dependencies
jest.mock(validatePluginNamePath, () => ({
  validatePluginName: jest.fn((p) => p),
}));
jest.mock(validateOptionalFuncsPath, () => ({
  validateOptionalFuncs: jest.fn(),
}));
jest.mock(normalizeAllMethodsPath, () => ({
  normalizeAllMethods: jest.fn((p) => p),
}));
jest.mock(validateSameMethodsPath, () => ({
  validateSameMethods: jest.fn(),
}));
jest.mock(normalizeIsOptionsPath, () => ({
  normalizeIsOptions: jest.fn(({ plugin: p }) => p),
}));
jest.mock(normalizeGetOptionsPath, () => ({
  normalizeGetOptions: jest.fn(({ plugin: p }) => p),
}));

// Require the function under test AFTER mocking dependencies
const { normalizePlugin } = require(srcPath);

describe('normalizePlugin', () => {
  const ParentError = class CustomError extends Error {}

  beforeEach(() => {
    jest.clearAllMocks()
  })

  it('should throw TypeError if plugin is not a plain object', () => {
    expect(() => normalizePlugin('string', ParentError)).toThrow(TypeError)
    expect(() => normalizePlugin(null, ParentError)).toThrow(TypeError)
    expect(() => normalizePlugin([], ParentError)).toThrow(TypeError)
    expect(() => normalizePlugin(123, ParentError)).toThrow(TypeError)
    expect(() => normalizePlugin(() => {}, ParentError)).toThrow(TypeError)
  })

  it('should include the ParentError name in the error message', () => {
    expect(() => normalizePlugin('invalid', ParentError)).toThrow(
      `The "plugins" option of "${ParentError.name}.subclass()" must be an array of plugin objects: invalid`,
    )
  })

  it('should call validatePluginName with the plugin', () => {
    const plugin = { name: 'test' }
    const { validatePluginName } = require(validatePluginNamePath)

    normalizePlugin(plugin, ParentError)
    expect(validatePluginName).toHaveBeenCalledWith(plugin)
  })

  it('should call validateOptionalFuncs with the result from validatePluginName', () => {
    const plugin = { name: 'test' }
    const pluginA = { name: 'validated' }
    const { validatePluginName } = require(validatePluginNamePath)
    const { validateOptionalFuncs } = require(validateOptionalFuncsPath)

    validatePluginName.mockReturnValue(pluginA)
    normalizePlugin(plugin, ParentError)
    expect(validateOptionalFuncs).toHaveBeenCalledWith(pluginA)
  })

  it('should call normalizeAllMethods with the plugin', () => {
    const plugin = { name: 'test' }
    const pluginA = { name: 'validated' }
    const { validatePluginName } = require(validatePluginNamePath)
    const { normalizeAllMethods } = require(normalizeAllMethodsPath)

    validatePluginName.mockReturnValue(pluginA)
    normalizePlugin(plugin, ParentError)
    expect(normalizeAllMethods).toHaveBeenCalledWith(pluginA)
  })

  it('should call validateSameMethods with the result from normalizeAllMethods', () => {
    const plugin = { name: 'test' }
    const pluginA = { name: 'validated' }
    const pluginB = { name: 'normalized' }
    const { validatePluginName } = require(validatePluginNamePath)
    const { normalizeAllMethods } = require(normalizeAllMethodsPath)
    const { validateSameMethods } = require(validateSameMethodsPath)

    validatePluginName.mockReturnValue(pluginA)
    normalizeAllMethods.mockReturnValue(pluginB)
    normalizePlugin(plugin, ParentError)
    expect(validateSameMethods).toHaveBeenCalledWith(pluginB)
  })

  it('should call normalizeIsOptions with the result from validateSameMethods', () => {
    const plugin = { name: 'test' }
    const pluginA = { name: 'validated' }
    const pluginB = { name: 'normalized' }
    const pluginC = { name: 'is-options-normalized' }
    const { validatePluginName } = require(validatePluginNamePath)
    const { normalizeAllMethods } = require(normalizeAllMethodsPath)
    const { normalizeIsOptions } = require(normalizeIsOptionsPath)

    validatePluginName.mockReturnValue(pluginA)
    normalizeAllMethods.mockReturnValue(pluginB)
    normalizeIsOptions.mockReturnValue(pluginC)
    normalizePlugin(plugin, ParentError)
    expect(normalizeIsOptions).toHaveBeenCalledWith({ plugin: pluginB })
  })

  it('should call normalizeGetOptions with the result from normalizeIsOptions', () => {
    const plugin = { name: 'test' }
    const pluginA = { name: 'validated' }
    const pluginB = { name: 'normalized' }
    const pluginC = { name: 'is-options-normalized' }
    const pluginD = { name: 'get-options-normalized' }
    const { validatePluginName } = require(validatePluginNamePath)
    const { normalizeAllMethods } = require(normalizeAllMethodsPath)
    const { normalizeIsOptions } = require(normalizeIsOptionsPath)
    const { normalizeGetOptions } = require(normalizeGetOptionsPath)

    validatePluginName.mockReturnValue(pluginA)
    normalizeAllMethods.mockReturnValue(pluginB)
    normalizeIsOptions.mockReturnValue(pluginC)
    normalizeGetOptions.mockReturnValue(pluginD)
    normalizePlugin(plugin, ParentError)
    expect(normalizeGetOptions).toHaveBeenCalledWith({ plugin: pluginC })
  })

  it('should return the final processed plugin object', () => {
    const plugin = { name: 'test' }
    const finalPlugin = { name: 'final', foo: 'bar' }
    const { validatePluginName } = require(validatePluginNamePath)
    const { normalizeAllMethods } = require(normalizeAllMethodsPath)
    const { normalizeIsOptions } = require(normalizeIsOptionsPath)
    const { normalizeGetOptions } = require(normalizeGetOptionsPath)

    validatePluginName.mockReturnValue({ ...plugin, step1: true })
    normalizeAllMethods.mockReturnValue({ ...plugin, step2: true })
    normalizeIsOptions.mockReturnValue({ ...plugin, step3: true })
    normalizeGetOptions.mockReturnValue(finalPlugin)
    const result = normalizePlugin(plugin, ParentError)
    expect(result).toEqual(finalPlugin)
  })
})
